-- The club's first five sponsors, with the logos they sent (cleaned as the app cleans an upload: flattened, sized,
-- no metadata), so they are on show as soon as this is deployed. Names and logos only: what each one sponsors, a link
-- and any offer are for the club to add under More, Sponsors.
--
-- Only for a database that was already running before this migration was written (the club's own), and only while it
-- has no sponsors yet: a database made afresh (tests, a new developer's copy, the demo) applies every migration at
-- once, today or later, and stays empty.
do $$
declare
  s record;
  logo uuid;
  icon uuid;
begin
  if exists (select 1 from sponsors) then return; end if;
  if not exists (select 1 from public.schema_migrations where applied_at < timestamptz '2026-11-23 00:00+00') then return; end if;
  for s in
    select * from (values
    ('Banglatown Cash & Carry', 1, '#ffffff', '#ffffff',
     decode('', 'hex'),
     decode('', 'hex')),
    ('Morning Stars Care Ltd', 2, '#ffffff', '#ffffff',
     decode('', 'hex'),
     decode('', 'hex')),
    ('SAS Facilities', 3, '#1a4331', '#1a4331',
     decode('', 'hex'),
     decode('', 'hex')),
    ('Syed Capital Holdings', 4, '#0f2942', '#0f2942',
     decode('', 'hex'),
     decode('', 'hex')),
    ('A&S Accountancy Services', 5, '#0d1627', '#0d1627',
     decode('', 'hex'),
     decode('', 'hex'))
    ) as v (name, sort, logo_bg, icon_bg, logo_png, icon_png)
  loop
    insert into club_files (name, mime, size, data) values ('sponsor-logo.png', 'image/png', octet_length(s.logo_png), s.logo_png) returning id into logo;
    insert into club_files (name, mime, size, data) values ('sponsor-icon.png', 'image/png', octet_length(s.icon_png), s.icon_png) returning id into icon;
    insert into sponsors (name, sort, logo_file_id, logo_bg, icon_file_id, icon_bg) values (s.name, s.sort, logo, s.logo_bg, icon, s.icon_bg);
  end loop;
end $$;
